import{_ as o,o as a,c as i,ag as d}from"./chunks/framework.BwSLX4ak.js";const h=JSON.parse('{"title":"Kugou","description":"","frontmatter":{},"headers":[],"relativePath":"allmusic/kugou.md","filePath":"allmusic/kugou.md"}'),c={name:"allmusic/kugou.md"};function l(t,e,s,u,r,n){return a(),i("div",null,[...e[0]||(e[0]=[d('<h1 id="kugou" tabindex="-1">Kugou <a class="header-anchor" href="#kugou" aria-label="Permalink to &quot;Kugou&quot;">​</a></h1><p>AllMusic_Kugou 的 API ID 是 <code>kugou</code>。它提供酷狗关键词搜索、歌曲信息、封面、时间轴歌词和平台返回的可用播放地址，并支持从部分分享链接读取歌曲或歌单标识。</p><h2 id="搜索和默认音乐源" tabindex="-1">搜索和默认音乐源 <a class="header-anchor" href="#搜索和默认音乐源" aria-label="Permalink to &quot;搜索和默认音乐源&quot;">​</a></h2><p>按<a href="./#安装">音乐源安装步骤</a>加载后：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/music search kugou 稻香</span></span></code></pre></div><p>AllMusic 的 <code>defaultApi</code> 为 <code>kugou</code> 时可省略 API ID。酷狗歌曲常用 32 位十六进制 <code>hash</code>，歌单使用数字 ID。当前实现识别 <code>hash</code>、<code>specialid</code> / <code>special_id</code> 参数和支持的歌单路径；链接中的 <code>album_id</code> 与 <code>album_audio_id</code> 会作为歌曲解析信息保留。</p><h2 id="cookie-来源" tabindex="-1">Cookie 来源 <a class="header-anchor" href="#cookie-来源" aria-label="Permalink to &quot;Cookie 来源&quot;">​</a></h2><p>默认从 AllMusic 已加载的 <code>cookie.json</code> 中读取酷狗 Cookie。当前源码也支持独立传入酷狗 Cookie，按以下优先级选择：</p><ol><li>JVM 系统属性 <code>allmusic.kugou.cookie</code>。</li><li>环境变量 <code>ALLMUSIC_KUGOU_COOKIE</code>。</li><li>源码中的 Cookie 覆盖值（通常保持为空）。</li><li>没有覆盖值时，使用 AllMusic 的 Cookie 列表。</li></ol><p>独立 Cookie 便于同时使用不同音乐平台。应通过自己的服务启动配置管理真实值；修改环境变量需要重启服务端或代理。Cookie 有效性、歌曲可播放范围和所需设备字段以酷狗接口实际返回为准。缺少 Android 播放流程需要的 <code>mid</code> / <code>dfid</code> 时，日志会要求重新导出 Cookie。</p><p>扩展的 <code>reload(File)</code> 没有独立配置文件逻辑。代码中的 <code>KugouSong.debug</code> 当前默认是 <code>false</code>，旧 README 所述“默认开启”不适用于当前源码。</p><h2 id="从源码构建" tabindex="-1">从源码构建 <a class="header-anchor" href="#从源码构建" aria-label="Permalink to &quot;从源码构建&quot;">​</a></h2><p>把匹配 AllMusic 版本的核心 JAR 放进项目 <code>libs/</code>，执行：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gradlew.bat build</span></span></code></pre></div><p>Linux/macOS 使用 <code>./gradlew build</code>，产物在 <code>build/libs/</code>。版本号以 <code>build.gradle</code> 为准；运行时需要 AllMusic 提供核心与公共库。</p><p><a href="https://github.com/hutuyee/AllMusic_Kugou" target="_blank" rel="noreferrer">Kugou 源码</a> · <a href="./troubleshooting.html">常见问题</a></p>',16)])])}const g=o(c,[["render",l]]);export{h as __pageData,g as default};
